import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;

    static long power(long base, long exp) {
        long res = 1L;
        for (; exp > 0; exp >>= 1) {
            if ((exp & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
        }
        return res;
    }

    static long inverse(long x) {
        return power(x, MOD - 2);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = reader.readLine().split(" ");
        long n = Long.parseLong(parts[0]);
        long m = Long.parseLong(parts[1]);
        long l = Long.parseLong(parts[2]);
        long r = Long.parseLong(parts[3]);

        PrintWriter out = new PrintWriter(System.out);
        if (l == r) {
            out.println(1);
            out.flush();
            return;
        }

        long oddCount = ((r + 1) / 2) - (l / 2);
        long evenCount = (r / 2) - ((l - 1) / 2);
        long totalCells = n * m;

        long answer;
        if (totalCells % 2 == 1) {
            answer = power(oddCount + evenCount, totalCells);
        } else {
            long sum = (power(oddCount + evenCount, totalCells) + power(oddCount - evenCount, totalCells)) % MOD;
            answer = (sum * inverse(2)) % MOD;
        }
        out.println(answer);
        out.flush();
    }
}
